questionvariables.text:
mlist: [[["AE","BH","FBH"],["DA","BH","CBH"],["EG","CH","ACH"],["GH","AE","90"],["ACH","AHC","CBH","CHB","FBH","90"]],[["CH","BG","EBG"],["CD","BE","ABE"],["BC","EF","90"],["CG","BH","FBH"],["ABE","AEB","EBG","EGB","FBH","90"]],[["BF","AC","90"],["FG","DE","ADE"],["BD","AH","FHA"],["CD","BE","ABE"],["ABE","ADE","AED","FAH","FHA","90"]],[["CG","AH","EAH"],["BC","DE","ADE"],["DH","CE","AEC"],["GH","BF","90"],["ACE","ADE","AEC","EAH","GCH","90"]],[["FH","BG","DBG"],["BC","AH","DAH"],["AB","CF","90"],["CG","BH","FBH"],["DAH","DBG","DGB","FBH","FHB","90"]],[["AB","DE","90"],["HE","AC","BCA"],["CG","BH","FBH"],["EF","BD","ABD"],["ABD","BCA","EBF","FBH","FHB","90"]],[["BC","AE","90"],["BF","DE","AED"],["CD","FH","EFH"],["FG","AH","DAH"],["AED","AFE","DAH","EFH","EHF","90"]],[["AF","BG","DGB"],["HE","AG","DAG"],["BC","DE","ADE"],["BC","GH","90"],["ADE","AED","DAG","DBG","DGB","90"]],[["CG","BH","FBH"],["BD","AF","HFA"],["AE","CH","GCH"],["EF","CG","90"],["FBH","FHB","GCH","GHC","HFA","90"]],[["GH","DF","CDF"],["BC","GH","90"],["EG","AH","CAH"],["BC","DF","ADF"],["ADF","AFD","CAH","CDF","CHA","90"]]];
/* Design: match pairs of skew lines to angles, one fixed option list (alphabetical, with the right angle last). No option is right for two pairs and no pair has a second valid name among the options. Source: original. */
ix: 1+rand(10); MM: mlist[ix]; OPT: MM[5];
lab(o) := if o = "90" then "a right angle (90°)" else sconcat("angle ", o);
mk(k) := makelist([o, is(o = MM[k][3]), lab(o)], o, OPT);
opt1: mk(1); opt2: mk(2); opt3: mk(3); opt4: mk(4);
ta1: MM[1][3]; ta2: MM[2][3]; ta3: MM[3][3]; ta4: MM[4][3];
wr(k) := first(sublist(OPT, lambda([o], is(o # MM[k][3]))));
wa1: wr(1); wa2: wr(2); wa3: wr(3); wa4: wr(4);
why(k) := if MM[k][3] = "90" then sconcat(MM[k][1], " is at right angles to a face that contains ", MM[k][2], ", so the angle between them is \\(90^\\circ\\).")
  else sconcat("Move ", MM[k][1], " to ", charat(MM[k][3],1), charat(MM[k][3],2), ", which is parallel to it and meets ", MM[k][2],
  " at ", charat(MM[k][3],2), ": the angle is angle ", MM[k][3], ".");
wy1: why(1); wy2: why(2); wy3: why(3); wy4: why(4);
alla: [ta1, ta2, ta3, ta4];

feedbackvariables.text:
LS: "ABCDEFGH"; LT: [[0,0,0],[6,0,0],[6,4,0],[0,4,0],[0,0,3],[6,0,3],[6,4,3],[0,4,3]];
pt(c) := LT[ssearch(c, LS)]; vv(s) := pt(charat(s,2)) - pt(charat(s,1));
parl(s,t) := block([u,w], u: vv(s), w: vv(t), is(u[2]*w[3]-u[3]*w[2] = 0 and u[3]*w[1]-u[1]*w[3] = 0 and u[1]*w[2]-u[2]*w[1] = 0));
rvs(s) := sconcat(charat(s,2), charat(s,1));
la: MM[1][1]; lb: MM[1][2]; r90: is(ans1 = "90");
arm(m) := if is(m = la or rvs(m) = la or m = lb or rvs(m) = lb) then sconcat(m, " is one of the two lines") else if parl(m, la) then sconcat(m, " is parallel to ", la) else if parl(m, lb) then sconcat(m, " is parallel to ", lb) else sconcat(m, " is parallel to neither ", la, " nor ", lb);
m1: if r90 then "" else sconcat(charat(ans1,2), charat(ans1,1)); m3: if r90 then "" else sconcat(charat(ans1,2), charat(ans1,3));
nn(m) := is(not (m = la or rvs(m) = la or m = lb or rvs(m) = lb or parl(m, la) or parl(m, lb)));
d13: if r90 then "" else if nn(m1) and nn(m3) then sconcat("Neither ", m1, " nor ", m3, " is parallel to ", la, " or to ", lb) else sconcat(arm(m1), "; ", arm(m3));

